#include <vector>
#include <omp.h>

void reversePrefixSum(std::vector<int> const& x, std::vector<int> &output) {
    const int n = static_cast<int>(x.size());
    output.resize(n);
    if (n == 0) return;

    const int P = omp_get_max_threads();
    std::vector<long long> blockSum(P, 0);
    std::vector<long long> blockOffset(P, 0);

    #pragma omp parallel
    {
        const int tid = omp_get_thread_num();
        const int nth = omp_get_num_threads();

        // Split work into contiguous blocks by thread id.
        const int base = n / nth;
        const int rem  = n % nth;
        const int start = tid * base + (tid < rem ? tid : rem);
        const int len   = base + (tid < rem ? 1 : 0);
        const int end   = start + len; // exclusive

        long long localSum = 0;

        // Local reverse-prefix within the block: for i in [start,end),
        // output[i] = sum_{k=i}^{end-1} x[k]
        for (int i = end - 1; i >= start; --i) {
            localSum += static_cast<long long>(x[i]);
            output[i] = static_cast<int>(localSum);
        }

        blockSum[tid] = localSum;

        #pragma omp barrier

        // One thread computes offsets: for each block, how much sum of blocks to its "right"
        // (higher indices) should be added.
        #pragma omp single
        {
            long long running = 0;
            for (int t = nth - 1; t >= 0; --t) {
                blockOffset[t] = running;
                running += blockSum[t];
            }
        }

        #pragma omp barrier

        const long long add = blockOffset[tid];
        for (int i = start; i < end; ++i) {
            output[i] = static_cast<int>(static_cast<long long>(output[i]) + add);
        }
    }
}
